function chart(weights){const values=weights.map(r=>Number(r.value)),min=Math.min(...values)-.2,max=Math.max(...values)+.2;const points=weights.map((r,i)=>[20+(weights.length===1?140:i/(weights.length-1)*280),145-(Number(r.value)-min)/(max-min)*120]);return `<svg class="chart" viewBox="0 0 320 170" role="img" aria-label="体重变化趋势">${weights.length>1?`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#8b5b2f" stroke-width="3"/>`:''}${points.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#fcfbf5" stroke="#8b5b2f" stroke-width="2"/>`).join('')}</svg>`;}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#petpick')?.addEventListener('change',e=>{if(persist({...state,current:e.target.value}))render();});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{origin=b.dataset.add;editId=null;completeId=null;go('choose');});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{taskTab=b.dataset.tab;render();});document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=b.dataset.activity;go(origin==='plans'?'scheduleform':'operation');});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>go(b.dataset.mode==='record'?'recordform':'scheduleform'));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{origin=page;editId=b.dataset.detail;completeId=null;go('detail');});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{completeId=b.dataset.task;go('taskdetail');});document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{origin=page;completeId=b.dataset.complete;activity=state.tasks.find(t=>t.id===completeId).activity;editId=null;photos=[];go('recordform');});
document.querySelectorAll('form').forEach(f=>f.oninput=()=>dirty=true);


if(!$('#scheduleForm')?.closest('.ui-canvas'))$('#scheduleForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),at=new Date(f.get('at'));if(!(at>new Date()))return toast('请选择未来的计划时间');const days=Number(f.get('days'));if(f.get('repeat')==='interval'&&(!Number.isInteger(days)||days<1||days>365))return toast('间隔需为 1—365 的整数天');const t={id:id(),petId:f.get('petId'),activity,at:at.toISOString(),repeat:f.get('repeat'),days,note:f.get('note'),status:'pending'};if(persist({...state,tasks:[...state.tasks,t]})){dirty=false;go(origin==='recordform'?'plans':origin);toast('安排已保存，使用应用内待办');}});
const form=$('#recordForm');if(form){const t=state.tasks.find(t=>t.id===completeId);const preview=()=>{if(t?.repeat==='interval'){const at=form.elements.at.value;if(at)$('#nextPreview').innerHTML=`<h2>下次安排</h2><h3>${date(nextTime(at,t.days))} ${clock(nextTime(at,t.days))}</h3><small>按实际完成时间顺延 ${t.days} 天</small>`;}};form.elements.at.addEventListener('change',preview);preview();form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form),at=new Date(f.get('at'));if(!Number.isFinite(at.getTime())||at>new Date())return toast('实际时间不能在未来');if(activity==='体重'&&!(Number(f.get('value'))>0))return toast('体重必须大于 0');if(['日记','照片'].includes(activity)&&!f.get('note').trim()&&!photos.length)return toast('正文与照片至少填写一项');const old=state.records.find(r=>r.id===editId),r={...old,id:old?.id||id(),petId:t?.petId||f.get('petId'),activity,at:at.toISOString(),created:old?.created||new Date().toISOString(),value:f.get('value')||'',unit:f.get('unit')||'',product:f.get('product')||'',dose:f.get('dose')||'',note:f.get('note'),photos};let next;try{next=t?finishTask(state,t.id,r,'complete-'+t.id):{...state,records:old?state.records.map(x=>x.id===old.id?r:x):[...state.records,r]};}catch(err){return toast(err.message);}if(persist(next)){dirty=false;completeId=null;editId=old?.id||null;if(f.get('next')){origin='plans';go('scheduleform');}else go(t?'today':old?'detail':origin==='taskdetail'?'plans':origin);toast(t?'照护已完成，记录已保存':'记录已保存');}});}
$('#photoInput')?.addEventListener('change',async e=>{const files=[...e.target.files];if(files.length+photos.length>9)return toast('每条记录最多 9 张照片');try{for(const file of files){if(file.size>20*1024*1024)throw Error('单张照片不能超过 20MB');photos.push(await compress(file));}$('#photos').innerHTML=photos.map(p=>`<img src="${p}" alt="记录照片">`).join('');dirty=true;}catch(err){toast(err.message);}});
$('#editRecord')?.addEventListener('click',()=>{activity=state.records.find(r=>r.id===editId).activity;go('recordform');});$('#deleteRecord')?.addEventListener('click',()=>{if(confirm('删除这条记录？关联安排仍保持已完成，下次日期不会改变。')&&persist({...state,records:state.records.filter(r=>r.id!==editId)})){go(origin);toast('记录已删除');}});$('#cancelTask')?.addEventListener('click',()=>{if(confirm('取消本次安排并停止它的后续间隔安排？')&&persist({...state,tasks:state.tasks.map(t=>t.id===completeId?{...t,status:'cancelled'}:t)}))go('plans');});$('#addWeight')?.addEventListener('click',()=>{origin='health';activity='体重';editId=null;completeId=null;go('recordform');});$('#healthHistory')?.addEventListener('click',()=>{filter='健康';go('today');});$('#export')?.addEventListener('click',()=>download(state));$('#restore')?.addEventListener('change',async e=>{try{const data=JSON.parse(await e.target.files[0].text());validateBackup(data);if(!confirm(`将替换当前数据：${data.pets.length} 只宠物、${data.records.length} 条记录、${data.tasks.length} 个安排。继续前会下载当前备份。`))return;download(state);if(persist(withLedger(data))){ledgerUI.scope=state.ledgerScope;go(data.pets.length?'today':'welcome');toast('恢复完成');}}catch(err){toast('恢复失败：'+err.message);}});}
function validateBackup(s){validateLedger(s);if(s.version!==1||!Array.isArray(s.pets)||!Array.isArray(s.records)||!Array.isArray(s.tasks)||!Array.isArray(s.processed))throw Error('备份格式或版本不支持');const pets=new Set(s.pets.map(p=>p.id));if(pets.size!==s.pets.length||s.pets.some(p=>!p.id||typeof p.name!=='string'))throw Error('宠物数据无效');for(const list of [s.records,s.tasks]){if(new Set(list.map(x=>x.id)).size!==list.length)throw Error('重复数据标识');for(const x of list){if(!pets.has(x.petId)||!activities.some(a=>a[0]===x.activity)||!Number.isFinite(new Date(x.at).getTime()))throw Error('数据引用或日期无效');if(x.photos?.some(p=>typeof p!=='string'||!/^data:image\/(jpeg|png|webp);base64,/.test(p)))throw Error('照片格式无效');}}if(s.tasks.some(t=>!['pending','done','cancelled'].includes(t.status)))throw Error('安排状态无效');if(s.current!=='all'&&s.pets.length&&!pets.has(s.current))throw Error('当前宠物无效');}
function download(data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='POMEPET-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function compress(file){const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.72);}
