function bindPetSwipe(){
const reveal=(row,open)=>{document.querySelectorAll('.ui-pet-swipe').forEach(other=>{const active=other===row&&open;other.classList.toggle('swipe-open',active);other.querySelector('.ui-pet-delete').hidden=!active;});};
document.querySelectorAll('.ui-pet-swipe').forEach(row=>{let start=null,moved=false;row.addEventListener('pointerdown',e=>{moved=false;if(e.button!==0||e.target.closest('[data-delete-pet]'))return;start={x:e.clientX,y:e.clientY};moved=false;});row.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>18&&Math.abs(dx)>Math.abs(dy)*1.4){moved=true;reveal(row,dx<0);}});row.addEventListener('pointerup',()=>{start=null;});row.addEventListener('pointercancel',()=>{start=null;});row.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);row.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();reveal(row,true);row.querySelector('.ui-pet-delete').focus();}if(e.key==='ArrowRight'||e.key==='Escape'){e.preventDefault();reveal(row,false);row.querySelector('.ui-mine-pet').focus();}});});
document.querySelectorAll('[data-delete-pet]').forEach(b=>b.onclick=()=>{const p=state.pets.find(p=>p.id===b.dataset.deletePet);if(!p||!confirm('删除“'+p.name+'”的档案？对应记录和安排将一并移除，可在此页恢复。'))return;if(persist(deletePet(state,p.id))){render();toast('档案已删除，可恢复最近删除的档案');}});
$('#restoreDeletedPet')?.addEventListener('click',()=>{try{if(persist(restorePet(state))){render();toast('档案、记录和安排已恢复');}}catch(e){toast(e.message);}});
}

function startNewPet(){if(dirty&&!confirm('有未保存的内容，确定放弃？'))return;dirty=false;petDraft=null;petAvatar='';careSelection=null;careCategory='日常护理';go('petform');}


let companionDate=todayShanghai();setInterval(()=>{const day=todayShanghai();if(day!==companionDate){companionDate=day;if(page==='profile'&&!dirty)render();}},60000);

let floatingScrollTimer;window.addEventListener('scroll',()=>{const button=document.querySelector('.ui-floating-add');if(!button)return;button.classList.add('is-scrolling');clearTimeout(floatingScrollTimer);floatingScrollTimer=setTimeout(()=>{if(button.isConnected)button.classList.remove('is-scrolling');},800);},{passive:true});
